WITH inventory AS (
 SELECT 'META_CAFE24' platform,p.id::text AS source_ref,p.name AS original_name,p.display_name AS display_name,p.is_active AS active,NULL::text AS parent_name,NULL::text AS scope_key FROM meta_ads.products p
 UNION ALL SELECT 'COUPANG',p.id::text,p.standard_name,p.display_name,p.is_active,g.display_name,'LEGACY_COUPANG_SINGLE_UPLOAD' FROM meta_ads.coupang_products p LEFT JOIN meta_ads.coupang_product_groups g ON g.id=p.group_id
 UNION ALL SELECT 'NAVER_UNIT',u.id,u.payload->>'displayName',u.payload->>'displayName',u.payload->>'isActive'='true',parent.payload->>'displayName',u.payload->>'storeId' FROM public.canonical_sales_units u LEFT JOIN public.canonical_sales_units parent ON parent.id=u.payload->>'parentSalesUnitId' WHERE u.payload->>'storeId' IN('5ba1d3cf-7aee-4cd1-aecd-d44352f665dd','78f8cb08-ffe3-481a-94d7-be87ae93ed79') AND coalesce(u.payload->>'isStoreLevel','false')<>'true'
), rule_names AS (
 SELECT 'META' platform,r.product_id::text source_product,r.match_type::text match_type,r.pattern,r.is_active,r.valid_from::text valid_from,r.valid_to::text valid_to FROM meta_ads.product_match_rules r
)
SELECT jsonb_build_object('observedAt',now(),'catalog',(SELECT jsonb_agg(to_jsonb(i) ORDER BY platform,display_name,source_ref) FROM inventory i),'metaNameRules',(SELECT jsonb_agg(to_jsonb(r)) FROM rule_names r),'unifiedProducts',(SELECT jsonb_agg(jsonb_build_object('id',id,'canonicalName',canonical_name,'active',active,'version',version)) FROM meta_ads.unified_products),'unifiedRules',(SELECT jsonb_agg(jsonb_build_object('id',id,'kind',kind,'productId',product_id,'platform',platform,'scopeKey',scope_key,'payload',payload,'validFrom',valid_from,'validTo',valid_to,'active',active,'version',version)) FROM meta_ads.unified_rules),'publicationDays',(SELECT jsonb_agg(jsonb_build_object('platform',platform,'scopeKey',scope_key,'date',business_date,'runId',run_id)) FROM meta_ads.unified_source_publications),'privacy','Product names/configuration and partition metadata only; no customer data or source payloads') AS inventory;
